--- from: Assets/BundleResources/Prefabs/Activity/ActivityRegressionRewardPopUpDialog.prefab > name: ActivityRegressionRewardPopUpDialog
---@class RegressionPurchaseDialog
---@field Env                            RegressionPurchaseDialog
---@field controller                        Engine.UI.UILuaDialog
---@field ClickClose                        UnityEngine.RectTransform
---@field TextTitle                        UnityEngine.RectTransform
---@field ImgRole                        UnityEngine.RectTransform
---@field ScrollView                        SuperScrollView.LoopGridView
---@field BtnClose                        UnityEngine.RectTransform
local RegressionPurchaseDialog = Class("RegressionPurchaseDialog")

function RegressionPurchaseDialog:__init()
    self.data = nil
    self.activityUuid = nil
    self.sdkEventHandler = nil
end

function RegressionPurchaseDialog:__delete()
    self.data = nil
    self.controller = nil
    self.activityUuid = nil
    self.sdkEventHandler = nil
end

function RegressionPurchaseDialog:Awake()
    self.activityUuid = checkNumber(self.controller.Argument.parameters.activityUuid)
    self.sdkEventHandler = Events.AddListener(Constants.EventNames.EVENT_SDK, Bind(self, self.OnEventSDKPayHandler))
    SetButtonAction(self.ClickClose, function()
        UIModule.BackDialog()
    end)
    SetButtonAction(self.BtnClose, function()
        UIModule.BackDialog()
    end)
end

function RegressionPurchaseDialog:OnFocus(focus)
end

---支付成功处理逻辑
function RegressionPurchaseDialog:OnEventSDKPayHandler(parameters)
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        GameUtils.Request(Interfaces.RegressMallGift, {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                local jsonData = response.data
                self.data = table.values(checkTable(jsonData.regressGift))
                self:RefreshUI()
            end
        end)
    end
end

function RegressionPurchaseDialog:RefreshUI()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitGridView(#self.data, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, #self.data)
    end

end
--region helper
function RegressionPurchaseDialog:OnGetItemByIndex(view, index)
    local luaIndex = index + 1
    ---@type ActivityDirectDrawMallProductDojo
    local cellData = self.data[luaIndex]
    local cell = view:NewListViewItem("OverseaMallGiftPackNode")

    ---@type RegressionGiftPackNode
    local scr = CfUtils.GetLuaScr(cell, ActivityMallGiftPackNodePath)
    if scr then
        scr:Refresh(cellData,cellData.pos, function(data, position)
            self:OnItemAction(data, position)
        end)
    end
    return cell
end

function RegressionPurchaseDialog:OnItemAction(cellData, position)
    local data = {
        productId = cellData.productId,
        activityUuid = self.activityUuid,
    }
    GameUtils.Request(Interfaces.OverseaStoreFreeDraw, data,
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local responseData = checkTable(response.data)
                    cellData.currentStock = checkNumber(cellData.currentStock) - 1
                    if #responseData.rewards > 0 then
                        GoodsUtils.DrawRewards(responseData.rewards)
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                        Events.Broadcast(Constants.EventNames.RegressMallRedDotHintEvent)
                    end
                    self:RefreshUI()
                end
            end
    )
end

function RegressionPurchaseDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local isFinish = false
        GameUtils.Request(Interfaces.RegressMallGift, {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                local jsonData = response.data
                self.data = table.values(checkTable(jsonData.regressGift))
            end
            isFinish = true
        end)
        while not isFinish do
            coroutine.yield()
        end
        ---更新界面
        self:RefreshUI()
    end))
    return coWait
end

function RegressionPurchaseDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self.sdkEventHandler then
            Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.sdkEventHandler)
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return RegressionPurchaseDialog